static bool read_shader(struct vkd3d_shader_code *shader, FILE *f)
{
	size_t size = 4096;
	struct stat st;
	size_t pos = 0;
	uint8_t *data;
	size_t ret;
	memset(shader, 0, sizeof(*shader));
	if (fstat(fileno(f), &st) == -1)
	{
		fprintf(stderr, "Could not stat input.");
		return false;
	}
	if (S_ISREG(st.st_mode))
		size = st.st_size;
	if (!(data = malloc(size)))
	{
		fprintf(stderr, "Out of memory.");
		return false;
	}
	for (;;)
	{
		if (pos >= size)
		{
			if (size > SIZE_MAX / 2 || !(data = realloc(data, size * 2)))
			{
				fprintf(stderr, "Out of memory.");
				free(data);
				return false;
			}
			size *= 2;
		}
		if (!(ret = fread(&data[pos], 1, size - pos, f)))
			break;
		pos += ret;
	}
	if (!feof(f))
	{
		free(data);
		return false;
	}
	shader->code = data;
	shader->size = pos;
	return true;
}

